effect.shader:
float u_xlat0;
float u_xlat1;
float u_xlat2;
void main()
{
    u_xlat0 = _white_point + -9.99999975e-05;
    u_xlat0 = min(u_xlat0, _black_point);
    u_xlat1 = u_xlat0 + 9.99999975e-05;
    u_xlat1 = max(u_xlat1, _white_point);
    u_xlat1 = (-u_xlat0) + u_xlat1;
    u_xlat2 = texture(inputImg, acScreenNorm.xy).x;
    u_xlat0 = (-u_xlat0) + u_xlat2;
    u_xlat0 = u_xlat0 / u_xlat1;
    u_xlat0 = u_xlat0 + _curve_offset;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlat1 = u_xlat0 * u_xlat2;
    u_xlat1 = clamp(u_xlat1, 0.0, 1.0);
    fragColor.xyz = (int(_curve_calculation) != 0) ? vec3(u_xlat0) : vec3(u_xlat1);
    fragColor.w = 1.0;
    return;
}
